import { Linking } from 'react-native';

// Listen for deep links
const subscription = Linking.addEventListener('url', ({url}) => {
  console.log('Received URL:', url);
});

// Check if a URL can be opened
Linking.canOpenURL('mailto:test@example.com').then(canOpen => {
  if (canOpen) Linking.openURL('mailto:test@example.com');
});

// Get URL that opened the app
Linking.getInitialURL().then(url => console.log('Initial URL:', url));

// Open settings
Linking.openSettings();

// Android send intent
Linking.sendIntent('android.intent.action.VIEW', [{key: 'id', value: 123}]);

// Clean up
subscription.remove();
